-- PostgreSQL fresh-deployment baseline. Existing MySQL migration checksums are unchanged.

-- Mirrors the consolidated MySQL domain baseline; forward changes require migrations for both vendors.

CREATE EXTENSION IF NOT EXISTS citext;

CREATE OR REPLACE FUNCTION yak_touch_update_timestamp() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF (to_jsonb(NEW) - COALESCE(TG_ARGV[1:array_upper(TG_ARGV, 1)], ARRAY[]::text[]))
      IS DISTINCT FROM (to_jsonb(OLD) - COALESCE(TG_ARGV[1:array_upper(TG_ARGV, 1)], ARRAY[]::text[]))
      AND (to_jsonb(NEW)->TG_ARGV[0]) IS NOT DISTINCT FROM (to_jsonb(OLD)->TG_ARGV[0]) THEN
    NEW := jsonb_populate_record(NEW, jsonb_build_object(TG_ARGV[0], CURRENT_TIMESTAMP));
  END IF;
  RETURN NEW;
END $$;

CREATE TABLE "yak_semantic_standard" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "project_id" bigint NOT NULL,
  "kind" citext NOT NULL CHECK (length("kind") <= 16),
  "std_code" citext NOT NULL CHECK (length("std_code") <= 64),
  "std_name" citext NOT NULL CHECK (length("std_name") <= 128),
  "status" citext DEFAULT 'ENABLED' NOT NULL CHECK (length("status") <= 16),
  "version" integer DEFAULT 1 NOT NULL,
  "sort_order" integer DEFAULT 0 NOT NULL,
  "is_preset" smallint DEFAULT 0 NOT NULL,
  "description" citext CHECK (length("description") <= 512),
  "scope" citext CHECK (length("scope") <= 16),
  "layer" citext CHECK (length("layer") <= 64),
  "rule_expr" citext CHECK (length("rule_expr") <= 1024),
  "example" citext CHECK (length("example") <= 256),
  "type_code" citext CHECK (length("type_code") <= 64),
  "std_type" citext CHECK (length("std_type") <= 64),
  "source_mapping" text,
  "code_set_code" citext CHECK (length("code_set_code") <= 64),
  "code_value" citext CHECK (length("code_value") <= 256),
  "code_label" citext CHECK (length("code_label") <= 256),
  "unit_code" citext CHECK (length("unit_code") <= 64),
  "unit_type" citext CHECK (length("unit_type") <= 64),
  "caliber_code" citext CHECK (length("caliber_code") <= 64),
  "cal_rule" citext CHECK (length("cal_rule") <= 1024),
  "business_desc" citext CHECK (length("business_desc") <= 512),
  "level_code" citext CHECK (length("level_code") <= 64),
  "mask_rule" citext CHECK (length("mask_rule") <= 512),
  "created_by" citext NOT NULL CHECK (length("created_by") <= 64),
  "create_time" timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
  "update_time" timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX "yak_semantic_standard_idx_yak_semantic_standard_kind" ON "yak_semantic_standard" ("project_id", "kind", "status");

CREATE UNIQUE INDEX "yak_semantic_standard_uk_yak_semantic_standard" ON "yak_semantic_standard" ("project_id", "kind", "std_code");

CREATE TRIGGER "yak_semantic_standard_touch" BEFORE UPDATE ON "yak_semantic_standard" FOR EACH ROW EXECUTE FUNCTION yak_touch_update_timestamp('update_time');

